package com.paylens.backend.service;
import com.paylens.backend.dto.AuditEventResponse; import com.paylens.backend.model.*; import com.paylens.backend.repository.AuditEventRepository; import java.util.*; import org.springframework.stereotype.Service;
@Service public class AuditService { private final AuditEventRepository repository; public AuditService(AuditEventRepository repository){this.repository=repository;} public void record(String decisionId,AuditEventType type,ActorType actorType,String actorId,String description){repository.save(new AuditEvent("evt_"+UUID.randomUUID(),decisionId,type,actorType,actorId,description,"{}"));} public List<AuditEventResponse> list(String decisionId){var events=decisionId==null?repository.findAllByOrderByCreatedAtDesc():repository.findByDecisionIdOrderByCreatedAtDesc(decisionId);return events.stream().map(e->new AuditEventResponse(e.getEventId(),e.getDecisionId(),e.getEventType(),e.getActorType(),e.getActorId(),e.getDescription(),e.getCreatedAt())).toList();} }
